  (match Sys.getenv_opt "GILLIAN_NATIVE_SMT_CONTEXT_DIR", Sys.getenv_opt "SMT_TIMEOUT" with
   | Some _, None ->
       [Alcotest.test_case "wrapped filter counter exact native query model and cache" `Quick
          (with_total wrapped_filter_counter_original);
        Alcotest.test_case "wrapped filter counter renamed and reversed alias native models" `Quick
          (with_total wrapped_filter_counter_names);
        Alcotest.test_case "wrapped filter counter failed hints full fallback and contradiction" `Quick
          (with_total wrapped_filter_counter_fallback);
        Alcotest.test_case "wrapped filter counter eligibility ambiguity and old priority" `Quick
          (with_total wrapped_filter_counter_guards)]
   | _ -> [])

(* Full observed strict-positive Keep state, before the old numeric witness's
   two literal guesses. The original native maximum-safe bits are restored
   exactly; Expr.pp's rounded decimal is not used as a new premise. *)
let strict_nonblank_filter_fixture label =
  let fs = parse_gil_set [
    "(! (u16\"length\" -e- #loopOutKeys))";
    "(! (#lvar_1430 v== -0.))";
    "(! ((num_to_int #n) == 0.))";
    "(! ((num_to_utf16 #lvar_1430) -e- #loopOutKeys))";
    "(! ((u16-trim #dhHead) == u16\"\"))";
    "(is_int #lvar_1429)";
    "(is_int #lvar_1430)";
    "(is_int #n)";
    "(is_int (num_to_int #n))";
    "(is_int (#lvar_1429 + 1.))";
    "(is_int (#lvar_1430 + 1.))";
    "(is_int ((num_to_int #n) - #lvar_1429))";
    "(is_int ((num_to_int #n) - (#lvar_1429 + 1.)))";
    "(is_int ((num_to_int #n) - (#lvar_1430 + 1.)))";
    "(0i i<= (l-len #dhTailValues))";
    "(0i i<= (l-len #loopChosen))";
    "(0i i<= (l-len #loopLocals))";
    "(0i i<= (l-len #loopPrefix))";
    "(0i i<= (l-len #lvar_1587))";
    "(0i i<= (as_int (#lvar_1429 - 0.)))";
    "(0i i<= (as_int (#n - 0.)))";
    "(0i i<= (as_int (#n - #lvar_1429)))";
    "(0. < #lvar_1429)";
    "(0. <= #lvar_1430)";
    "(0. <= #n)";
    "(0. <= (num_to_int #n))";
    "(0. <= (#lvar_1429 + 1.))";
    "(0. <= (#lvar_1430 + 1.))";
    "(0. <= ((num_to_int #n) - #lvar_1429))";
    "(0. <= ((num_to_int #n) - (#lvar_1429 + 1.)))";
    "(0. <= ((num_to_int #n) - (#lvar_1430 + 1.)))";
    "(#lvar_1429 < #n)";
    "(#lvar_1429 < (num_to_int #n))";
    "(#lvar_1429 <= 4294967294.)";
    "(#lvar_1429 <= 4294967295.)";
    "(#lvar_1430 <= 4294967294.)";
    "(#lvar_1430 <= 4294967295.)";
    "(#lvar_1430 <= #lvar_1429)";
    "(#n <= 4294967295.)";
    "((num_to_int #n) == #n)";
    "((num_to_int #n) <= 4294967295.)";
    "((num_to_int #n) <= 9007199254740991.)";
    "((l-len #dhTailValues) i<= 4294967294i)";
    "((u16-len #dhHead) i<= 9007199254740991i)";
    "((u16-len (u16-trim #dhHead)) i<= (u16-len #dhHead))";
    "((as_int #lvar_1429) == (l-len #loopPrefix))";
    "((as_int #lvar_1430) == (l-len #loopChosen))";
    "((as_int #n) == (1i i+ ((l-len #dhTailValues) i+ (l-len #loopPrefix))))";
    "((as_int #n) == (1i i+ ((l-len #dhTailValues) i+ (as_int #lvar_1429))))";
    "((as_int (#lvar_1429 + 1.)) == (1i i+ (as_int #lvar_1429)))";
    "((as_int (#lvar_1430 + 1.)) == (1i i+ (as_int #lvar_1430)))";
    "((#lvar_1429 + 1.) <= 4294967295.)";
    "((#lvar_1429 + 1.) <= (num_to_int #n))";
    "((#lvar_1430 + 1.) <= 4294967295.)";
    "((#lvar_1430 + 1.) <= (num_to_int #n))";
    "(((l-len #dhTailValues) i+ (l-len #loopPrefix)) i<= 4294967294i)";
    "(-u- (#lvar_1425, #lvar_1426) == -u- (#lvar_1492, #lvar_1493))";
    "(-u- (#lvar_1425, #lvar_1426) == -u- (-{ (num_to_utf16 #lvar_1429) }-,\n                                      #dhPrefixKeys, #dhTailKeys))";
  ] in
  let gamma = Hashtbl.create 18 in
  List.iter (fun (name,typ) -> Hashtbl.add gamma name typ) [
    "#lvar_1492",Type.SetType;
    "#lvar_1426",Type.SetType;
    "#lvar_1429",Type.NumberType;
    "#lvar_1588",Type.SetType;
    "#loopPrefix",Type.ListType;
    "#lvar_1425",Type.SetType;
    "#dhTailKeys",Type.SetType;
    "#dhPrefixKeys",Type.SetType;
    "#n",Type.NumberType;
    "#loopOutKeys",Type.SetType;
    "#lvar_1493",Type.SetType;
    "#lvar_1587",Type.ListType;
    "#loopLocals",Type.ListType;
    "#dhHead",Type.Utf16Type;
    "#dhTailValues",Type.ListType;
    "#lvar_1430",Type.NumberType;
    "#loopChosen",Type.ListType;
    "#lvar_1586",Type.Utf16Type;
  ];
  Alcotest.(check int) "complete original strict-nonblank assertions" 58 (Expr.Set.cardinal fs);
  Alcotest.(check int) "complete original strict-nonblank Gamma" 18 (Hashtbl.length gamma);
  if label = "saved" then fs,gamma else
    let rename = object inherit [_] Visitors.endo
      method! visit_LVar () _ n = Expr.LVar (n ^ "_strict_head_" ^ label) end in
    let fs = Expr.Set.fold (fun e acc -> Expr.Set.add (rename#visit_expr () e) acc) fs Expr.Set.empty in
    let renamed = Hashtbl.create 18 in
    Hashtbl.iter (fun n typ -> Hashtbl.add renamed (n ^ "_strict_head_" ^ label) typ) gamma;
    fs,renamed

let strict_nonblank_filter_check label fs gamma head status =
  let before=nonblank_counter_rows () and atoms=Expr.Set.elements fs
  and types=nonblank_counter_types gamma in
  let role n = Expr.LVar (if label="saved" then n else n ^ "_strict_head_" ^ label) in
  let lower=role "#lvar_1429" and upper=role "#n"
  and position=role "#lvar_1430" and item=role "#dhHead" in
  let pins head = List.fold_left (fun fs (role,value) -> Expr.Set.add
    (bin ValueEqual role value) fs) fs
    [lower,Expr.num 1.;upper,Expr.num 2.;position,Expr.num 0.;
     item,nonblank_utf16 head] in
  let model,contexts=pending_context_capture (fun () -> Smt.check_sat fs gamma) in
  finite_number_bound_complete label before contexts status;
  ignore (strict_counter_endpoint label before contexts "optional-nonblank-counter"
    (pins (if status="unsat" then head else "a")) gamma
    (if head=" a" || status="unsat" then "unsat" else "sat"));
  if head=" a" then ignore (strict_counter_endpoint label before contexts
    "optional-nonblank-whitespace-counter" (pins " a") gamma "sat");
  Alcotest.(check bool) "complete original model status" (status="sat") (Option.is_some model);
  Option.iter (fun model ->
    strict_counter_values label model gamma lower upper (Some (1.,2.));
    let name = function Expr.LVar n -> n | _ -> assert false in
    primary_check_lift label model gamma [name position,Literal.Num 0.;
      name item,Literal.Utf16String (Utils.Utf16.of_canonical head)]) model;
  let old=nonblank_counter_rows () in
  ignore (Smt.check_sat fs gamma);
  Alcotest.(check bool) "strict head complete-key cache emits no endpoint" true
    (old=nonblank_counter_rows ());
  nonblank_counter_retained label fs gamma atoms types

let strict_nonblank_filter_native () = with_nonblank_counter_trace (fun () ->
  let check = strict_nonblank_filter_check in
  let fs,gamma = strict_nonblank_filter_fixture "saved" in check "saved" fs gamma "a" "sat";
  let fs,gamma = strict_nonblank_filter_fixture "alpha" in check "alpha" fs gamma "a" "sat";
  let fs,gamma = strict_nonblank_filter_fixture "whitespace" in
  let head=Expr.LVar "#dhHead_strict_head_whitespace" in
  check "whitespace" (Expr.Set.add (not_ (bin ValueEqual head (nonblank_utf16 "a"))) fs)
    gamma " a" "sat";
  let fs,gamma = strict_nonblank_filter_fixture "blank" in
  check "blank" (Expr.Set.add (bin ValueEqual (Expr.LVar "#dhHead_strict_head_blank")
    (nonblank_utf16 "")) fs) gamma "" "unsat")

let tests = tests @
  (match Sys.getenv_opt "GILLIAN_NATIVE_SMT_CONTEXT_DIR", Sys.getenv_opt "SMT_TIMEOUT" with
   | Some _, None -> [Alcotest.test_case
       "strict-positive Keep exact full native models and failed-hint fallback" `Quick
       (with_total strict_nonblank_filter_native)]
   | _ -> [])

(* The same observed state after one owned prefix element is unfolded:
   five exact formula replacements, not a reduced satisfiability projection. *)
let expanded_nonblank_filter_fixture () =
  let fs,gamma = strict_nonblank_filter_fixture "saved" in
  let removed = parse_gil_set [
    "(((l-len #dhTailValues) i+ (l-len #loopPrefix)) i<= 4294967294i)";
    "((as_int #lvar_1429) == (l-len #loopPrefix))";
    "((as_int #n) == (1i i+ ((l-len #dhTailValues) i+ (l-len #loopPrefix))))";
    "(-u- (#lvar_1425, #lvar_1426) == -u- (-{ (num_to_utf16 #lvar_1429) }-,\n                                      #dhPrefixKeys, #dhTailKeys))";
    "(0i i<= (l-len #loopPrefix))";
  ] and added = parse_gil_set [
    "(((l-len #dhTailValues) i+ (l-len #lvar_1587)) i<= 4294967293i)";
    "((as_int #lvar_1429) == (1i i+ (l-len #lvar_1587)))";
    "((as_int #n) == (2i i+ ((l-len #dhTailValues) i+ (l-len #lvar_1587))))";
    "((u16-len #lvar_1586) i<= 9007199254740991i)";
    "(-u- (#lvar_1425, #lvar_1426) == -u- (-{ u16\"0\",\n                                      (num_to_utf16 #lvar_1429) }-,\n                                      #dhTailKeys, #lvar_1588))";
  ] in
  Alcotest.(check bool) "all five old prefix assertions actually present" true
    (Expr.Set.subset removed fs);
  let fs = Expr.Set.union (Expr.Set.diff fs removed) added in
  List.iter (fun n -> Alcotest.(check bool) "eliminated prefix name was typed" true
    (Hashtbl.mem gamma n); Hashtbl.remove gamma n) ["#loopPrefix";"#dhPrefixKeys"];
  Alcotest.(check int) "complete expanded-prefix FS" 58 (Expr.Set.cardinal fs);
  Alcotest.(check int) "complete expanded-prefix Gamma" 16 (Hashtbl.length gamma);
  fs,gamma

let expanded_nonblank_filter_native () = with_nonblank_counter_trace (fun () ->
  let fs,gamma = expanded_nonblank_filter_fixture () in
  strict_nonblank_filter_check "saved" fs gamma "a" "sat";
  let reverse = Expr.Set.add (not_ (bin ValueEqual (nonblank_utf16 "")
    (Expr.UnOp (Utf16Trim,Expr.LVar "#dhHead")))) fs in
  strict_nonblank_filter_check "saved" reverse gamma "a" "sat";
  let sentinel = Utils.Utf16.of_canonical "\t" in
  let pinned = Expr.Set.add (bin ValueEqual (Expr.LVar "#lvar_1586")
    (Expr.Lit (Literal.Utf16String sentinel))) fs in
  strict_nonblank_filter_check "saved" pinned gamma "a" "sat";
  let model = Option.get (Smt.check_sat pinned gamma) in
  primary_check_lift "passive prefix element remains original" model gamma
    ["#lvar_1586",Literal.Utf16String sentinel];
  (* Head-role ambiguity is a separate well-typed guard fixture. Do not make
     that structural check depend on solving a second synthetic heap state. *)
  let other=Expr.LVar "#lvar_1586" and head=Expr.LVar "#dhHead"
  and lower=Expr.LVar "#lvar_1429" and upper=Expr.LVar "#n"
  and position=Expr.LVar "#lvar_1430" in
  let gamma=Hashtbl.create 5 in
  List.iter (fun n -> Hashtbl.add gamma n Type.NumberType)
    ["#lvar_1429";"#n";"#lvar_1430"];
  List.iter (fun n -> Hashtbl.add gamma n Type.Utf16Type)
    ["#dhHead";"#lvar_1586"];
  let ambiguous=Expr.Set.of_list [Expr.UnOp (IsInt,lower);Expr.UnOp (IsInt,upper);
    Expr.UnOp (IsInt,position);bin FLessThan (Expr.num 0.) lower;
    bin FLessThan lower upper;bin FLessThanEqual upper (Expr.num 10.);
    bin FLessThanEqual lower (Expr.num 10.);
    bin FLessThanEqual position (Expr.num 10.);
    bin FLessThanEqual (Expr.num 0.) position;bin FLessThanEqual position lower;
    bin ValueEqual position (Expr.num 0.);
    not_ (bin Equal (Expr.UnOp (Utf16Trim,head)) (nonblank_utf16 ""));
    not_ (bin Equal (Expr.UnOp (Utf16Trim,other)) (nonblank_utf16 ""));
    bin ValueEqual other (nonblank_utf16 "a");
    bin ValueEqual head (nonblank_utf16 "a")] in
  (* The one-guard counterpart must be eligible, making the two-head decline
     causal rather than an accidental failure of another structural guard. *)
  let one = Expr.Set.remove
    (not_ (bin Equal (Expr.UnOp (Utf16Trim,other)) (nonblank_utf16 ""))) ambiguous in
  strict_nonblank_filter_check "saved" one gamma "a" "sat";
  let before=nonblank_counter_rows () in
  ignore (strict_counter_run ~hint:(1.,2.,"sat") ~wanted:(1.,2.)
    "distinct trimmed heads decline strict mode" ambiguous gamma
    (Expr.LVar "#lvar_1429") (Expr.LVar "#n") "sat");
  Alcotest.(check bool) "ambiguous head emits no nonblank guess" true
    (List.for_all (fun row -> not (List.mem (smt_result_field "caller" row)
      ["optional-nonblank-counter";"optional-nonblank-whitespace-counter"]))
      (List.filter (fun row -> not (List.mem row before)) (nonblank_counter_rows ()))) )

let tests = tests @
  (match Sys.getenv_opt "GILLIAN_NATIVE_SMT_CONTEXT_DIR", Sys.getenv_opt "SMT_TIMEOUT" with
   | Some _, None -> [Alcotest.test_case
       "strict nonblank opened-prefix full model, passive head and ambiguity" `Quick
       (with_total expanded_nonblank_filter_native)]
   | _ -> [])


(* The reached invariant has a weak-zero counter and fresh Number binders.
   The unchanged complete head witness must precede the counter-only guess. *)
let weak_nonblank_precedence_native () = with_nonblank_counter_trace (fun () ->
  let fs,gamma = nonblank_counter_fixture () in
  Hashtbl.add gamma "#fresh_k" Type.NumberType;
  Hashtbl.add gamma "#fresh_to" Type.NumberType;
  let fs = Expr.Set.union fs (parse_gil_set [
    "(is_int #fresh_k)"; "(#fresh_k <= #n)";
    "(! (#fresh_to v== -0.))"
  ]) in
  let before = nonblank_counter_rows () and atoms = Expr.Set.elements fs
  and types = nonblank_counter_types gamma in
  let model,contexts = pending_context_capture (fun () -> Smt.check_sat fs gamma) in
  finite_number_bound_complete "weak-nonblank-first" before contexts "sat";
  ignore (strict_counter_endpoint "weak-nonblank-first" before contexts
    "optional-nonblank-counter" (nonblank_counter_pins fs 0. 1. 0. "a") gamma "sat");
  Alcotest.(check int) "only the complete head witness is dispatched" 1
    (List.length (List.filter (fun row -> not (List.mem row before))
      (nonblank_counter_rows ())));
  let model = match model with Some m -> m | None -> Alcotest.fail "missing full model" in
  nonblank_counter_model_values "weak-nonblank-first" model gamma 0. 1. 0. "a";
  let closed = nonblank_counter_rows () in
  ignore (Smt.check_sat fs gamma);
  Alcotest.(check bool) "complete model cache emits no second query" true
    (closed = nonblank_counter_rows ());
  nonblank_counter_retained "weak-nonblank-first" fs gamma atoms types)

let weak_nonblank_precedence_fallback () = with_nonblank_counter_trace (fun () ->
  let original,gamma = nonblank_counter_fixture () in
  let guard = not_ (bin Equal (Expr.UnOp (Utf16Trim,Expr.LVar "#dhHead"))
    (nonblank_utf16 "")) in
  let check label fs rejected_heads =
    let before = nonblank_counter_rows () and atoms = Expr.Set.elements fs
    and types = nonblank_counter_types gamma in
    let model,contexts = pending_context_capture (fun () -> Smt.check_sat fs gamma) in
    finite_number_bound_complete label before contexts "sat";
    Alcotest.(check bool) (label ^ " actual full-state fallback model") true
      (Option.is_some model);
    let fresh = List.filter (fun row -> not (List.mem row before))
      (nonblank_counter_rows ()) in
    if rejected_heads then (
      ignore (strict_counter_endpoint label before contexts "optional-nonblank-counter"
        (nonblank_counter_pins fs 0. 1. 0. "a") gamma "unsat");
      ignore (strict_counter_endpoint label before contexts "optional-nonblank-whitespace-counter"
        (nonblank_counter_pins fs 0. 1. 0. " a") gamma "unsat");
      Alcotest.(check int) "two full hinted rejections followed by native SAT" 3
        (List.length fresh);
      let lifted = Hashtbl.create 1 in
      Smt.lift_model (Option.get model) gamma (Hashtbl.add lifted)
        (Expr.Set.singleton (Expr.LVar "#dhHead"));
      let head = Hashtbl.find lifted "#dhHead" in
      Alcotest.(check bool) "fallback does not fabricate either rejected head" true
        (head <> nonblank_utf16 "a" && head <> nonblank_utf16 " a")
    ) else Alcotest.(check bool) "missing trim guard never dispatches head hints" true
      (List.for_all (fun row -> not (List.mem (smt_result_field "caller" row)
        ["optional-nonblank-counter";"optional-nonblank-whitespace-counter"])) fresh);
    let counter_pins = List.fold_left (fun acc (name,value) -> Expr.Set.add
      (bin ValueEqual (Expr.LVar name) (Expr.num value)) acc)
      fs ["#k",0.;"#n",1.] in
    ignore (strict_counter_endpoint label before contexts "optional-nonempty-counter"
      counter_pins gamma "sat");
    nonblank_counter_retained label fs gamma atoms types in
  check "missing-trim-guard" (Expr.Set.remove guard original) false;
  let fs = List.fold_left (fun fs value -> Expr.Set.add
    (not_ (bin ValueEqual (Expr.LVar "#dhHead") (nonblank_utf16 value))) fs)
    original ["a";" a"] in
  check "both-head-hints-rejected" fs true)

let tests = tests @
  (match Sys.getenv_opt "GILLIAN_NATIVE_SMT_CONTEXT_DIR", Sys.getenv_opt "SMT_TIMEOUT" with
   | Some _, None -> [
       Alcotest.test_case "weak nonblank complete head witness precedes counter-only guess" `Quick
         (with_total weak_nonblank_precedence_native);
       Alcotest.test_case "weak nonblank missing guard and rejected hints retain native fallback" `Quick
         (with_total weak_nonblank_precedence_fallback)]
   | _ -> [])

let stable_assertion_dedup_native () = with_nonblank_counter_trace (fun () ->
  let x = Expr.LVar "#dedup_x" and y = Expr.LVar "#dedup_y" in
  let gamma = Hashtbl.create 2 in
  Hashtbl.add gamma "#dedup_x" Type.NumberType;
  Hashtbl.add gamma "#dedup_y" Type.NumberType;
  let formatting value =
    let formatted = Expr.UnOp (NumberToUtf16,value) in
    [bin Equal formatted (nonblank_utf16 "0");
     bin Equal (Expr.UnOp (Utf16Len,formatted)) (Expr.int 1);
     not_ (bin Equal formatted (nonblank_utf16 "1"))] in
  let shared = Expr.Set.of_list (formatting x @ formatting y) in
  let positive = bin ValueEqual x (Expr.num 0.)
  and negative = bin ValueEqual y (Expr.num (-0.)) in
  let sat = Expr.Set.add positive (Expr.Set.add negative shared) in
  (* Reverse operands so both contradictory pins survive even a literal
     ordering which identifies the two floating-point zeros. *)
  let conflicting = bin ValueEqual (Expr.num (-0.)) x in
  let unsat = Expr.Set.add conflicting sat in
  let run label fs expected =
    let caller = "control-dedup-" ^ label in
    let before = nonblank_counter_rows () and atoms = Expr.Set.elements fs
    and types = nonblank_counter_types gamma in
    let model,contexts = pending_context_capture (fun () ->
      Smt.exec_sat ~caller_kind:caller fs gamma) in
    Alcotest.(check bool) (label ^ " real native verdict") expected (Option.is_some model);
    ignore (nonblank_counter_observe label before caller
      (if expected then "sat" else "unsat") fs gamma);
    Alcotest.(check int) (label ^ " one submitted query") 1 (List.length contexts);
    let context = List.hd contexts in
    let text = function `String s -> s | _ -> Alcotest.fail "expected native text" in
    let commands = match pending_context_field "encoded_assertions" context with
      | `List xs -> List.map (fun x -> Sexplib.Sexp.of_string (text x)) xs
      | _ -> Alcotest.fail "expected actual command list" in
    let assertions = List.filter (function
      | Sexplib.Sexp.List (Sexplib.Sexp.Atom "assert" :: _) -> true
      | _ -> false) commands in
    (* Eight/nine main constraints, four distinct formatter bridge facts and
       two literal-parser facts must all survive; uniqueness alone would let
       a broken encoder discard distinct intrinsic facts. *)
    Alcotest.(check int) (label ^ " every distinct constraint retained")
      (if expected then 14 else 15) (List.length assertions);
    let rec contains atom = function
      | Sexplib.Sexp.Atom value -> value = atom
      | Sexplib.Sexp.List values -> List.exists (contains atom) values in
    let intrinsic head terms = List.filter (function
      | Sexplib.Sexp.List [Sexplib.Sexp.Atom "assert";
          Sexplib.Sexp.List (Sexplib.Sexp.Atom op :: _)] as fact ->
          op = head && List.for_all (fun term -> contains term fact) terms
      | _ -> false) assertions in
    List.iter (fun variable ->
      Alcotest.(check int) (label ^ variable ^ " formatter roundtrip retained once")
        1 (List.length (intrinsic "or" [variable;"num2utf16";"utf162num"]));
      Alcotest.(check int) (label ^ variable ^ " decimal recognition retained once")
        1 (List.length (intrinsic "=>" [variable;"gil_uint32_decimal_value"])))
      ["$$dedup_x";"$$dedup_y"];
    Alcotest.(check int) (label ^ " both literal-parser facts retained once")
      2 (List.length (intrinsic "=" ["utf162num"]));
    Alcotest.(check int) (label ^ " exact repeated assertions removed")
      (List.length assertions) (List.length (List.sort_uniq Stdlib.compare assertions));
    let query = text (pending_context_field "query" context) in
    let dump = nonblank_counter_read (Filename.concat "gillian_smt_queries" query) in
    let marker = "Encoded as SMT Query:\n" in
    let start = Str.search_forward (Str.regexp_string marker) dump 0 + String.length marker in
    Alcotest.(check string) (label ^ " inspected commands are the actual submitted dump")
      (String.trim (text (pending_context_field "encoded_assertion_dump" context)))
      (String.trim (String.sub dump start (String.length dump - start)));
    let pin variable bits reversed =
      let v = "(Elem (Num $$dedup_" ^ variable ^ "))"
      and n = "(Elem (Num ((_ to_fp 11 53) #x" ^ bits ^ ")))" in
      Sexplib.Sexp.of_string ("(assert (= " ^
        (if reversed then n ^ " " ^ v else v ^ " " ^ n) ^ "))") in
    let position wanted =
      match List.find_opt (fun (_,command) -> command = wanted)
        (List.mapi (fun i command -> i,command) assertions) with
      | Some (i,_) -> i | None -> Alcotest.fail (label ^ " lost distinct zero constraint") in
    let px = position (pin "x" "0000000000000000" false)
    and ny = position (pin "y" "8000000000000000" false) in
    Alcotest.(check bool) (label ^ " main assertion order retained") true (px < ny);
    if not expected then ignore (position (pin "x" "8000000000000000" true));
    nonblank_counter_retained label fs gamma atoms types;
    model in
  let model = Option.get (run "sat" sat true) in
  let lifted = Hashtbl.create 2 in
  Smt.lift_model model gamma (Hashtbl.add lifted) (Expr.Set.of_list [x;y]);
  List.iter (fun (name,wanted) -> match Hashtbl.find_opt lifted name with
    | Some (Expr.Lit (Literal.Num actual)) -> Alcotest.(check int64)
        (name ^ " native signed-zero bits retained") (Int64.bits_of_float wanted)
        (Int64.bits_of_float actual)
    | _ -> Alcotest.fail "missing native signed-zero witness")
    ["#dedup_x",0.;"#dedup_y",-0.];
  ignore (run "unsat" unsat false))

let tests = tests @
  (match Sys.getenv_opt "GILLIAN_NATIVE_SMT_CONTEXT_DIR", Sys.getenv_opt "SMT_TIMEOUT" with
   | Some _, None -> [Alcotest.test_case "stable exact SMT assertion deduplication and signed zeros"
       `Quick (with_total stable_assertion_dedup_native)]
   | _ -> [])

let formatted_index_fixture label =
  let index = Expr.LVar ("#formatted_index_" ^ label)
  and keys = Expr.LVar ("#formatted_keys_" ^ label) in
  let gamma = Hashtbl.create 3 in
  (match index,keys with LVar i,LVar k ->
    Hashtbl.add gamma i Type.NumberType; Hashtbl.add gamma k Type.SetType
   | _ -> assert false);
  Hashtbl.add gamma "#unused_formatted_frame" Type.BooleanType;
  let next = bin FPlus index (Expr.num 1.) in
  let formatted = Expr.UnOp (NumberToUtf16,index) in
  let fs = Expr.Set.of_list [Expr.UnOp (IsInt,index);Expr.UnOp (IsInt,next);
    bin FLessThanEqual (Expr.num 0.) index;
    bin FLessThan index (Expr.num 4294967295.);
    bin FLessThanEqual next (Expr.num 4294967295.);
    bin ILessThanEqual (Expr.int 0) (Expr.UnOp (NumToInt,index));
    not_ (bin SetMem formatted keys);
    bin Equal (Expr.UnOp (NumberToUtf16,Expr.UnOp (ToUint32Op,
      bin FPlus index (Expr.num 0.)))) formatted;
    bin Equal (Expr.UnOp (NumToInt,next))
      (bin IPlus (Expr.int 1) (Expr.UnOp (NumToInt,index)))] in
  fs,gamma,index

let formatted_index_attempt label fs gamma expected guess =
  let before = nonblank_counter_rows () and atoms = Expr.Set.elements fs
  and types = nonblank_counter_types gamma in
  let model,contexts = pending_context_capture (fun () ->
    Smt.formatted_index_model fs gamma) in
  Alcotest.(check bool) (label ^ " real complete optional verdict") expected
    (Option.is_some model);
  let index = Expr.LVar ("#formatted_index_" ^ label) in
  let submitted = Expr.Set.add (bin ValueEqual index (Expr.num guess)) fs in
  let caller = "optional-formatted-index" in
  ignore (nonblank_counter_observe label before caller
    (if expected then "sat" else "unsat") submitted gamma);
  Alcotest.(check int) (label ^ " exactly one native complete attempt") 1 (List.length contexts);
  let context = List.hd contexts in
  List.iter (fun (key,want) -> Alcotest.(check bool) (label ^ " policy " ^ key) true
    (pending_context_field key context = want))
    ["raw_unknown",`Bool true;"timeout_ms",`String "1000";"phase_selection",`Int 3];
  Alcotest.(check bool) (label ^ " native model validation retained") true
    (pending_context_field "model_validate" (pending_context_field "initial_options" context)
       = `String "true");
  nonblank_counter_retained label fs gamma atoms types;
  model

let formatted_index_native () = with_nonblank_counter_trace (fun () ->
  List.iter (fun (label,positive) ->
    let fs,gamma,index = formatted_index_fixture label in
    let fs = if positive then Expr.Set.add (bin FLessThan (Expr.num 0.) index) fs else fs in
    let guess = if positive then 1. else 0. in
    let model = Option.get (formatted_index_attempt label fs gamma true guess) in
    let name = match index with LVar name -> name | _ -> assert false in
    primary_check_lift label model gamma [name,Literal.Num guess];
    let before = nonblank_counter_rows () in
    let cached,contexts = pending_context_capture (fun () -> Smt.check_sat fs gamma) in
    Alcotest.(check bool) (label ^ " public dispatch returns a native model") true (Option.is_some cached);
    ignore (nonblank_counter_observe (label ^ " public") before "optional-formatted-index" "sat"
      (Expr.Set.add (bin ValueEqual index (Expr.num guess)) fs) gamma);
    Alcotest.(check bool) (label ^ " public complete endpoint is observed") true (contexts <> []);
    let files = nonblank_counter_files () in
    ignore (Smt.check_sat fs gamma);
    Alcotest.(check bool) (label ^ " complete-key cache needs no new native query") true
      (files = nonblank_counter_files ())) ["zero",false;"positive",true])

let formatted_index_fallback () = with_nonblank_counter_trace (fun () ->
  let fs,gamma,index = formatted_index_fixture "miss" in
  let nonzero = Expr.Set.add (bin FLessThanEqual (Expr.num 2.) index) fs in
  ignore (formatted_index_attempt "miss" nonzero gamma false 0.);
  let before = nonblank_counter_rows () in
  let model,contexts = pending_context_capture (fun () -> Smt.check_sat nonzero gamma) in
  Alcotest.(check bool) "failed guess preserves a full native nonzero model" true (Option.is_some model);
  ignore (nonblank_counter_observe "miss fallback" before "required-complete" "sat" nonzero gamma);
  Alcotest.(check bool) "required complete fallback was actually submitted" true (contexts <> []);
  let negative,gamma,index = formatted_index_fixture "negative" in
  let negative = Expr.Set.add (bin ValueEqual index (Expr.num (-0.))) negative in
  Alcotest.(check bool) "fixed raw negative zero declines the positive-zero hint" true
    (Option.is_none (Smt.formatted_index_model negative gamma));
  let model = Option.get (Smt.check_sat negative gamma) in
  let name = match index with LVar name -> name | _ -> assert false in
  primary_check_lift "raw negative zero fallback" model gamma [name,Literal.Num (-0.)];
  let contradiction,gamma,index = formatted_index_fixture "conflict" in
  let contradiction = Expr.Set.add (bin SetMem (Expr.UnOp (NumberToUtf16,index))
    (Expr.LVar "#formatted_keys_conflict")) contradiction in
  ignore (formatted_index_attempt "conflict" contradiction gamma false 0.);
  Alcotest.(check bool) "contradictory full frame cannot become a SAT witness" true
    (Option.is_none (Smt.check_sat contradiction gamma));
  let plain,gamma,index = formatted_index_fixture "decline" in
  let before = nonblank_counter_rows () in
  Alcotest.(check bool) "missing original integrality declines the hint" true
    (Option.is_none (Smt.formatted_index_model (Expr.Set.remove (Expr.UnOp (IsInt,index)) plain) gamma));
  Alcotest.(check bool) "ineligible shape submits no solver guess" true
    (before = nonblank_counter_rows ()))

let tests = tests @
  (match Sys.getenv_opt "GILLIAN_NATIVE_SMT_CONTEXT_DIR", Sys.getenv_opt "SMT_TIMEOUT" with
   | Some _, None -> [
       Alcotest.test_case "formatted index complete native witness and public cache" `Quick
         (with_total formatted_index_native);
       Alcotest.test_case "formatted index missed hint raw zero conflict and fallback" `Quick
         (with_total formatted_index_fallback)]
   | _ -> [])

(* The original alias frame may also retain the next-prefix length bound.
   This is the complete current15 frame, not an inferred cast lower bound. *)
let positive_trace_next_length_fixture label =
  let fs,gamma,index,name,one = positive_trace_current_frame_fixture 0 label in
  let fs = Expr.Set.add (one "((1i i+ (as_int #index)) i<= (l-len #values))") fs in
  Alcotest.(check int) "whole alias plus next-length frame" 15 (Expr.Set.cardinal fs);
  fs,gamma,index,name,one

let positive_trace_next_length_models () = with_nonblank_counter_trace (fun () ->
  List.iter (fun label ->
    let fs,gamma,index,_,one = positive_trace_next_length_fixture label in
    positive_trace_run (label ^ "-next-length") fs gamma index "sat" "sat" 1.;
    let rows = nonblank_counter_rows () in
    let cached = Smt.check_sat fs gamma in
    Alcotest.(check bool) "same complete-key cache reuses actual SAT model" true
      (Option.is_some cached && rows = nonblank_counter_rows ());
    let missing = Expr.Set.remove (one "(is_int #index)") fs in
    Alcotest.(check bool) "missing original index support still declines" true
      (Option.is_none (Smt.positive_trace_index_witness_query missing gamma)))
    ["saved";"next_length_alpha";"collision"])

let positive_trace_next_length_fallback () = with_nonblank_counter_trace (fun () ->
  List.iter (fun (label,value) ->
    let fs,gamma,index,_,_ = positive_trace_next_length_fixture label in
    positive_trace_run label (Expr.Set.add (bin ValueEqual index (Expr.num value)) fs)
      gamma index "unsat" "sat" value)
    ["next-length-positive-zero",0.;"next-length-negative-zero",-.0.;
     "next-length-index-two",2.])

let positive_trace_next_length_frame () = with_nonblank_counter_trace (fun () ->
  let fs,gamma,index,name,one = positive_trace_next_length_fixture "next_length_frame" in
  let frame = one "(#current == u16\"unchanged frame\")" in
  let fs = Expr.Set.add frame fs in
  positive_trace_run "next-length-UTF16-frame" fs gamma index "sat" "sat" 1.;
  let fs = Expr.Set.add (not_ frame) fs in
  let hinted = match Smt.positive_trace_index_witness_query fs gamma with
    | Some hinted -> hinted | None -> Alcotest.fail "whole contradictory frame must reach native check" in
  let before = nonblank_counter_rows () and caller = "control-next-length-frame-contradiction" in
  let original = Expr.Set.elements fs and types = nonblank_counter_types gamma in
  let rejected,contexts = pending_context_capture (fun () ->
    Alcotest.(check bool) "optional complete frame contradiction cannot yield SAT" true
      (Option.is_none (Smt.positive_trace_index_model fs gamma));
    Option.is_none (Smt.exec_sat ~caller_kind:caller fs gamma)) in
  Alcotest.(check bool) "required original contradiction independently rejects" true rejected;
  positive_trace_complete "next-length-frame" before contexts "unsat";
  ignore (positive_trace_selected "next-length-frame" contexts "optional-positive-trace-index" hinted gamma);
  ignore (positive_trace_selected "next-length-frame" contexts caller fs gamma);
  ignore (nonblank_counter_observe "next-length-frame" before "optional-positive-trace-index" "unsat" hinted gamma);
  ignore (nonblank_counter_observe "next-length-frame" before caller "unsat" fs gamma);
  Alcotest.(check bool) "all original frame atoms and Gamma entries unchanged" true
    (List.equal Expr.equal original (Expr.Set.elements fs) && types=nonblank_counter_types gamma);
  Alcotest.(check bool) "actual current role is retained" true
    (Hashtbl.find_opt gamma (name "#current")=Some Type.Utf16Type))

let tests = tests @
  (match Sys.getenv_opt "GILLIAN_NATIVE_SMT_CONTEXT_DIR", Sys.getenv_opt "SMT_TIMEOUT" with
   | Some _, None -> [
       Alcotest.test_case "positive trace next length whole native models alpha and public cache" `Quick
         (with_total positive_trace_next_length_models);
       Alcotest.test_case "positive trace next length hint miss signed zero complete fallback" `Quick
         (with_total positive_trace_next_length_fallback);
       Alcotest.test_case "positive trace next length retained UTF16 frame contradiction" `Quick
         (with_total positive_trace_next_length_frame)]
   | _ -> [])

(* Complete retained prefix/current/suffix frame. The nonempty suffix is
   expressed by a weak successor bound plus a numerical disequality. *)
let nonempty_suffix_fixture label =
  let name x = if label="saved" then x else x ^ "_suffix_" ^ label in
  let rename = object inherit [_] Visitors.endo
    method! visit_LVar () _ x = Expr.LVar (name x)
  end in
  let one text = Expr.Set.choose (parse_gil_set [text]) |> rename#visit_expr () in
  let fs = Expr.Set.of_list (List.map one [
    "(! ((#index + 1.) == #n))";
    "(is_int #index)"; "(is_int #n)"; "(is_int (#index + 1.))";
    "(0i i<= (l-len #prefix))"; "(0i i<= (l-len #suffix))";
    "(0i i<= ((as_int #n) i+ (-1i i* (as_int (#index + 1.)))))";
    "(0. <= #index)"; "(0. <= #n)"; "(0. <= (#index + 1.))";
    "(#current == l-nth(l+(#prefix,l+({{#current}},#suffix)),(as_int #index)))";
    "(#index < #n)"; "(#index <= 4294967295.)"; "(#n <= 4294967295.)";
    "((as_int #index) == (l-len #prefix))";
    "((u16-len #current) i<= 9007199254740991i)";
    "((as_int #n) == (1i i+ ((l-len #prefix) i+ (l-len #suffix))))";
    "((as_int #n) i<= 4294967295i)";
    "((as_int (#index + 1.)) == (1i i+ (as_int #index)))";
    "((as_int (#index + 1.)) i<= 4294967295i)";
    "((#index + 1.) <= 4294967295.)"; "((#index + 1.) <= #n)";
    "(((l-len #prefix) i+ (l-len #suffix)) i<= 4294967294i)";
    "(((as_int #n) i+ (-1i i* (as_int (#index + 1.)))) == (l-len #suffix))";
    "((-1i i+ ((-1i i* (as_int #index)) i+ (as_int #n))) == ((as_int #n) i+ (-1i i* (as_int (#index + 1.)))))";
    "(((as_int #n) i+ (-1i i* (as_int (#index + 1.)))) i< ((as_int #n) i+ (-1i i* (as_int #index))))";
    "((1i i+ (l-len #suffix)) == ((-1i i* (as_int #index)) i+ (as_int #n)))"
  ]) in
  let gamma = Hashtbl.create 5 in
  List.iter (fun (n,t) -> Hashtbl.add gamma (name n) t)
    ["#current",Type.Utf16Type;"#index",Type.NumberType;"#n",Type.NumberType;
     "#prefix",Type.ListType;"#suffix",Type.ListType];
  Alcotest.(check int) "whole retained prefix/suffix frame" 27 (Expr.Set.cardinal fs);
  fs,gamma,Expr.LVar (name "#index"),Expr.LVar (name "#n"),one

let nonempty_suffix_run label fs gamma lower upper hint wanted =
  let _,_,hint_status = hint in
  let model = strict_counter_run ~hint ~required:(hint_status="unsat") ~wanted
    label fs gamma lower upper "sat"
    |> Option.get in
  positive_trace_replay label model gamma fs lower (fst wanted)

let nonempty_suffix_models () = with_nonblank_counter_trace (fun () ->
  List.iter (fun label ->
    let fs,gamma,lower,upper,one = nonempty_suffix_fixture label in
    nonempty_suffix_run label fs gamma lower upper (0.,2.,"sat") (0.,2.);
    let before = nonblank_counter_rows () in
    Alcotest.(check bool) "same complete query uses checked cache without a new endpoint" true
      (Option.is_some (Smt.check_sat fs gamma) && before=nonblank_counter_rows ());
    if label="saved" then (
      let reversed = Expr.Set.add (one "(! (#n == (#index + 1.)))")
        (Expr.Set.remove (one "(! ((#index + 1.) == #n))") fs) in
      nonempty_suffix_run "reversed numerical disequality" reversed gamma lower upper
        (0.,2.,"sat") (0.,2.))) ["saved";"alpha";"collision"])

let nonempty_suffix_fallback () = with_nonblank_counter_trace (fun () ->
  let fs,gamma,lower,upper,one = nonempty_suffix_fixture "fallback" in
  let no_gap = Expr.Set.remove (one "(! ((#index + 1.) == #n))") fs in
  nonempty_suffix_run "old weak successor keeps zero-one seed" no_gap gamma lower upper
    (0.,1.,"sat") (0.,1.);
  let fixed = strict_counter_pins fs lower upper 1. 3. in
  nonempty_suffix_run "failed zero-two seed keeps original full SAT" fixed gamma
    lower upper (0.,2.,"unsat") (1.,3.);
  let raw_zero = strict_counter_pins fs lower upper (-.0.) 2. in
  nonempty_suffix_run "raw negative zero survives positive-zero hint miss" raw_zero
    gamma lower upper (0.,2.,"unsat") (-.0.,2.))

let nonempty_suffix_frame () = with_nonblank_counter_trace (fun () ->
  let fs,gamma,lower,upper,one = nonempty_suffix_fixture "frame" in
  let frame = one "(#current == u16\"retained nonnumeric frame\")" in
  let fs = Expr.Set.add frame fs in
  nonempty_suffix_run "whole UTF16/list frame SAT" fs gamma lower upper (0.,2.,"sat") (0.,2.);
  let fs = Expr.Set.add (not_ frame) fs in
  ignore (strict_counter_run ~hint:(0.,2.,"unsat")
    "whole UTF16/list frame contradiction" fs gamma lower upper "unsat");
  let before = nonblank_counter_rows () and caller = "control-nonempty-suffix-full-frame" in
  let rejected,contexts = pending_context_capture (fun () ->
    Option.is_none (Smt.exec_sat ~caller_kind:caller fs gamma)) in
  Alcotest.(check bool) "independent original complete-frame UNSAT" true rejected;
  finite_number_bound_complete "whole original frame" before contexts "unsat";
  ignore (strict_counter_endpoint "whole original frame" before contexts caller fs gamma "unsat"))

let tests = tests @
  (match Sys.getenv_opt "GILLIAN_NATIVE_SMT_CONTEXT_DIR", Sys.getenv_opt "SMT_TIMEOUT" with
   | Some _, None -> [
       Alcotest.test_case "nonempty suffix full frame native models disequality and cache" `Quick
         (with_total nonempty_suffix_models);
       Alcotest.test_case "nonempty suffix old weak seed raw zero and full fallback" `Quick
         (with_total nonempty_suffix_fallback);
       Alcotest.test_case "nonempty suffix retained UTF16 list frame contradiction" `Quick
         (with_total nonempty_suffix_frame)]
   | _ -> [])


(* Original integrality atoms only. Rounding may stall a large successor;
   this precheck proves no strict progress and cannot replace a loop rank. *)
let integral_successor_fixture label step =
  let index = Expr.LVar ("#successor_" ^ label)
  and frame = Expr.LVar ("#successor_frame_" ^ label) in
  let gamma = Hashtbl.create 2 in
  (match index,frame with Expr.LVar n,Expr.LVar s ->
    Hashtbl.add gamma n Type.NumberType;
    Hashtbl.add gamma s Type.Utf16Type | _ -> assert false);
  let premise = Expr.UnOp (IsInt,index) in
  let failed = not_ (Expr.UnOp (IsInt,bin FPlus index (Expr.num step))) in
  let core = Expr.Set.of_list [premise;failed] in
  let full = Expr.Set.add
    (bin Equal frame (original_core_literal [65;32;66])) core in
  index,gamma,premise,failed,core,full

let integral_successor_observe label fs gamma core wanted =
  let original = Expr.Set.elements fs and types = nonblank_counter_types gamma in
  let before = nonblank_counter_rows () in
  let model,contexts = pending_context_capture (fun () -> Smt.check_sat fs gamma) in
  finite_number_bound_complete label before contexts wanted;
  Alcotest.(check bool) (label ^ " actual complete result") (wanted="sat")
    (Option.is_some model);
  (match core with
   | Some expected ->
       let row = nonblank_counter_observe label before "optional-original-core"
         "unsat" expected gamma in
       Alcotest.(check string) (label ^ " optional unknown stays inconclusive")
         "true" (smt_result_field "raw_unknown" row);
       Alcotest.(check string) (label ^ " unchanged optional timeout")
         (Smt.optional_timeout 5000) (smt_result_field "timeout_ms" row)
   | None ->
       Alcotest.(check bool) (label ^ " selector declined") true
         (List.for_all (fun c -> pending_context_field "caller" c
           <> `String "optional-original-core") contexts);
       ignore (strict_counter_endpoint label before contexts "required-complete"
         fs gamma wanted));
  nonblank_counter_retained label fs gamma original types;
  model

let integral_successor_original_core () = with_nonblank_counter_trace (fun () ->
  List.iter (fun label ->
    let _,gamma,_,_,core,full = integral_successor_fixture label 1. in
    Alcotest.(check bool) (label ^ " strict original subset") true
      (Expr.Set.subset core full && not (Expr.Set.equal core full));
    ignore (integral_successor_observe label full gamma (Some core) "unsat");
    let before = nonblank_counter_read "file.log" in
    Alcotest.(check bool) (label ^ " original full-key cache UNSAT") true
      (Option.is_none (Smt.check_sat full gamma));
    Alcotest.(check string) (label ^ " cached result adds no native endpoint")
      before (nonblank_counter_read "file.log")) ["plain";"renamed"])

let integral_successor_countercontrols () = with_nonblank_counter_trace (fun () ->
  let index,gamma,premise,_,_,full = integral_successor_fixture "fraction" 1. in
  let fs = Expr.Set.add (bin ValueEqual index (Expr.num 0.5))
    (Expr.Set.remove premise full) in
  let model = integral_successor_observe "missing-integrality" fs gamma None "sat" in
  positive_trace_replay "missing-integrality" (Option.get model) gamma fs index 0.5;
  let index,gamma,_,failed,_,full = integral_successor_fixture "no_goal" 1. in
  let fs = Expr.Set.add (bin ValueEqual index (Expr.num 0.))
    (Expr.Set.remove failed full) in
  let model = integral_successor_observe "missing-failed-goal" fs gamma None "sat" in
  positive_trace_replay "missing-failed-goal" (Option.get model) gamma fs index 0.;
  let index,gamma,_,_,_,full = integral_successor_fixture "half" 0.5 in
  let fs = Expr.Set.add (bin ValueEqual index (Expr.num 0.)) full in
  let model = integral_successor_observe "half-increment" fs gamma None "sat" in
  positive_trace_replay "half-increment" (Option.get model) gamma fs index 0.;
  let _,gamma,_,_,core,_ = integral_successor_fixture "exact" 1. in
  ignore (integral_successor_observe "no-proper-subset" core gamma None "unsat"))

let integral_successor_boundaries () = with_nonblank_counter_trace (fun () ->
  List.iter (fun (label,value) ->
    let index,gamma,_,_,core,full = integral_successor_fixture label 1. in
    let fs = Expr.Set.add (bin ValueEqual index (Expr.num value)) full in
    ignore (integral_successor_observe label fs gamma (Some core) "unsat"))
    ["positive_zero",0.;"negative_zero",-.0.;
     "stalled_large",9007199254740992.;"maximum_finite",Float.max_float];
  let index,gamma,premise,_,_,full = integral_successor_fixture "no_progress" 1. in
  let fs = full |> Expr.Set.remove
      (not_ (Expr.UnOp (IsInt,bin FPlus index (Expr.num 1.))))
    |> Expr.Set.add (bin ValueEqual index (Expr.num 9007199254740992.))
    |> Expr.Set.add (not_ (bin FLessThan index (bin FPlus index (Expr.num 1.)))) in
  assert (Expr.Set.mem premise fs);
  let model = integral_successor_observe "integrality-is-not-descent" fs gamma None "sat" in
  positive_trace_replay "integrality-is-not-descent" (Option.get model) gamma fs index
    9007199254740992.)

